selector_to_html = {"a[href=\"#submodules\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Submodules<a class=\"headerlink\" href=\"#submodules\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.viz._VIZ_DEPENDENCIES\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz._VIZ_DEPENDENCIES\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.</span></span><span class=\"sig-name descname\"><span class=\"pre\">_VIZ_DEPENDENCIES</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">('plotly',</span> <span class=\"pre\">'pyvista')</span></span></dt><dd></dd>", "a[href=\"core/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.core<a class=\"headerlink\" href=\"#module-pyskyfire.viz.core\" title=\"Link to this heading\">\u00b6</a></h1><h2>Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#attributes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#package-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Package Contents<a class=\"headerlink\" href=\"#package-contents\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"network_viz/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.network_viz<a class=\"headerlink\" href=\"#module-pyskyfire.viz.network_viz\" title=\"Link to this heading\">\u00b6</a></h1><p>Interactive HTML visualisation for <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">EngineNetwork</span></code> objects.</p><p>The visualiser deliberately treats the network topology as model data and the\nnode positions / edge bend points as presentation data.  This makes it useful\nboth as a script output today and as the basis for a future graphical editor.</p>", "a[href=\"injector_viz/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.injector_viz<a class=\"headerlink\" href=\"#module-pyskyfire.viz.injector_viz\" title=\"Link to this heading\">\u00b6</a></h1><p>Injector scenes and face views.</p><p><a class=\"reference internal\" href=\"injector_viz/InjectorComponent.html#pyskyfire.viz.injector_viz.InjectorComponent\" title=\"pyskyfire.viz.injector_viz.InjectorComponent\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">InjectorComponent</span></code></a> draws the wetted surface of every hole, its bore\nbehind the face, one colour per feed, optionally carrying each hole\u2019s flow from\nan <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">InjectorResult</span></code> as scene fields. Arrows from\neach hole to its impingement point can be added; they are annotation, not\nhardware.\n<a class=\"reference internal\" href=\"#pyskyfire.viz.injector_viz.plot_injector_face\" title=\"pyskyfire.viz.injector_viz.plot_injector_face\"><code class=\"xref py py-func docutils literal notranslate\"><span class=\"pre\">plot_injector_face()</span></code></a> is the same injector seen from the chamber: hole\noutlines, the jets projected onto the face, and where they meet.</p>", "a[href=\"engine_viz/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.engine_viz<a class=\"headerlink\" href=\"#module-pyskyfire.viz.engine_viz\" title=\"Link to this heading\">\u00b6</a></h1><p>Deprecated engine viewer compatibility API and legacy mesh helpers.</p>", "a[href=\"report/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.report<a class=\"headerlink\" href=\"#module-pyskyfire.viz.report\" title=\"Link to this heading\">\u00b6</a></h1><h2>Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.viz.missing\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.missing\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.</span></span><span class=\"sig-name descname\"><span class=\"pre\">missing</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">''</span></span></dt><dd></dd>", "a[href=\"heat_exchanger_component/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.heat_exchanger_component<a class=\"headerlink\" href=\"#module-pyskyfire.viz.heat_exchanger_component\" title=\"Link to this heading\">\u00b6</a></h1><p>Heat-exchanger geometry and results in the shared scene hierarchy.</p>", "a[href=\"backends/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.backends<a class=\"headerlink\" href=\"#module-pyskyfire.viz.backends\" title=\"Link to this heading\">\u00b6</a></h1><p>Rendering adapters for the common scene model.</p>", "a[href=\"plot_common/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.plot_common<a class=\"headerlink\" href=\"#module-pyskyfire.viz.plot_common\" title=\"Link to this heading\">\u00b6</a></h1><h2>Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"plot_ducts/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.plot_ducts<a class=\"headerlink\" href=\"#module-pyskyfire.viz.plot_ducts\" title=\"Link to this heading\">\u00b6</a></h1><p>Pressure along a solved duct, against arc length.</p>", "a[href=\"lookup_tables/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.lookup_tables<a class=\"headerlink\" href=\"#module-pyskyfire.viz.lookup_tables\" title=\"Link to this heading\">\u00b6</a></h1><h2>Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.viz._missing_dependencies\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz._missing_dependencies\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.</span></span><span class=\"sig-name descname\"><span class=\"pre\">_missing_dependencies</span></span></dt><dd></dd>", "a[href=\"components/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.components<a class=\"headerlink\" href=\"#module-pyskyfire.viz.components\" title=\"Link to this heading\">\u00b6</a></h1><p>Engineering objects adapted into local-coordinate scene hierarchies.</p>", "a[href=\"heat_exchanger/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.heat_exchanger<a class=\"headerlink\" href=\"#module-pyskyfire.viz.heat_exchanger\" title=\"Link to this heading\">\u00b6</a></h1><p>Heat-exchanger swept geometry and wall/flow report panels.</p>", "a[href=\"impeller_viz/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.impeller_viz<a class=\"headerlink\" href=\"#module-pyskyfire.viz.impeller_viz\" title=\"Link to this heading\">\u00b6</a></h1><p>Convenience plotting and surface export through the shared impeller scene.</p>", "a[href=\"plot_thermo/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.plot_thermo<a class=\"headerlink\" href=\"#module-pyskyfire.viz.plot_thermo\" title=\"Link to this heading\">\u00b6</a></h1><h2>Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#module-pyskyfire.viz\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz<a class=\"headerlink\" href=\"#module-pyskyfire.viz\" title=\"Link to this heading\">\u00b6</a></h1><h2>Submodules<a class=\"headerlink\" href=\"#submodules\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"plot_film_cooling/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.plot_film_cooling<a class=\"headerlink\" href=\"#module-pyskyfire.viz.plot_film_cooling\" title=\"Link to this heading\">\u00b6</a></h1><p>pyskyfire/viz/plot_film_cooling.py</p><p>PlotBase subclasses for visualising contour-based Grisson film cooling results.</p>", "a[href=\"sankey/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.sankey<a class=\"headerlink\" href=\"#module-pyskyfire.viz.sankey\" title=\"Link to this heading\">\u00b6</a></h1><p>Mass-flow Sankey diagrams for converged PyskyFire engine networks.</p><p>The diagram uses fluid stations as Sankey nodes and fluid blocks as the links\nbetween them.  This gives splitters and mergers their expected Sankey meaning:</p>", "a[href=\"scene/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.scene<a class=\"headerlink\" href=\"#module-pyskyfire.viz.scene\" title=\"Link to this heading\">\u00b6</a></h1><p>Renderer-independent scenes. Coordinates are metres; rotations are radians.</p>", "a[href=\"turbine_viz/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.turbine_viz<a class=\"headerlink\" href=\"#module-pyskyfire.viz.turbine_viz\" title=\"Link to this heading\">\u00b6</a></h1><p>Plotly figures of an axial turbine: triangles, passage, cascade and spanwise angles.</p><p>Each function takes one of the turbine objects and returns a <code class=\"docutils literal notranslate\"><span class=\"pre\">go.Figure</span></code>,\nready for <code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">Report.add_figure()</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">fig.show()</span></code>. Lengths are shown in\nmillimetres and angles in degrees. Pitchwise distances and angles are positive\nin the direction the rotor turns, as in <a class=\"reference internal\" href=\"../turbine/index.html#module-pyskyfire.turbine\" title=\"pyskyfire.turbine\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.turbine</span></code></a>.</p>", "a[href=\"plot_regen/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.plot_regen<a class=\"headerlink\" href=\"#module-pyskyfire.viz.plot_regen\" title=\"Link to this heading\">\u00b6</a></h1><h2>Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
